/**
 * 10x skill <name> — a short, terminal-sized glossary entry for one course
 * skill: its place in the 10x workflow, the problem it solves, when to run it,
 * what it writes and which skills sit next to it.
 *
 * Course scope follows `10x changelog`: `--course`, else the project's course,
 * else every course the account holds. Language follows `10x get`: `--lang`,
 * else the configured language, else English. Read-only: never prompts or writes.
 *
 * Overviews are generated by the 10x-toolkit from each SKILL.md, so they describe
 * the skill as published on the toolkit's master branch.
 */

import type { CAC } from "cac";
import { fetchSkillOverviews, type SkillOverview, type SkillOverviewLanguage } from "../lib/api-content";
import { requireAuth } from "../lib/auth-guard";
import { readToolConfig } from "../lib/config";
import { paint, STYLE, wrapText } from "../lib/format";
import { ExitCodes, type GlobalFlags, type OutputContext, output, outputError, resolveContext, sanitize, verbose } from "../lib/output";
import { type CourseScope, resolveCourseScope } from "./changelog";

interface SkillFlags extends GlobalFlags {
  course?: unknown;
  lang?: unknown;
}

const LANGUAGES: readonly SkillOverviewLanguage[] = ["en", "pl"];
const MAX_WIDTH = 100;
const MAX_SUGGESTIONS = 3;

export function registerSkillCommand(cli: CAC): void {
  cli
    .command("skill <name>", "Explain a 10x skill: problem, solution, when to use, artifacts, related skills")
    .option("--course <course>", "Look in one course (default: this project's course)")
    .option("--lang <lang>", "Language: en (default) or pl")
    .action(async (name: string, options: SkillFlags) => {
      const ctx = resolveContext(options);
      await runSkill(ctx, name, options);
    });
}

/** Accepts what a learner would type or paste: `10x-plan`, `/10x-plan`, `$10x-plan`, `plan`. */
export function normalizeSkillName(raw: string): string | null {
  const name = raw.trim().replace(/^[/$]/, "").toLowerCase();
  return /^[a-z0-9][a-z0-9-]*$/.test(name) ? name : null;
}

function editDistance(a: string, b: string): number {
  let previous = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const current = [i];
    for (let j = 1; j <= b.length; j++) {
      const substitution = (previous[j - 1] ?? 0) + (a[i - 1] === b[j - 1] ? 0 : 1);
      current[j] = Math.min((previous[j] ?? 0) + 1, (current[j - 1] ?? 0) + 1, substitution);
    }
    previous = current;
  }
  return previous[b.length] ?? 0;
}

/** The closest known names: shared substrings first, then likely typos. */
export function suggestSkills(query: string, names: string[]): string[] {
  const bare = query.replace(/^10x-/, "");
  // Short names are one typo apart from everything, so the tolerance scales with length.
  const tolerance = Math.max(1, Math.min(3, Math.floor(bare.length / 3)));
  const scored = names
    .map((name) => {
      const candidate = name.replace(/^10x-/, "");
      const contains = bare.length >= 2 && (candidate.includes(bare) || bare.includes(candidate));
      return { name, score: contains ? 0 : editDistance(bare, candidate) };
    })
    .filter(({ score }) => score <= tolerance)
    .sort((a, b) => a.score - b.score || a.name.localeCompare(b.name));
  return scored.slice(0, MAX_SUGGESTIONS).map(({ name }) => name);
}

export async function runSkill(ctx: OutputContext, rawName: string, options: SkillFlags): Promise<void> {
  // Validate usage before touching credentials so bad invocations exit 2.
  const name = normalizeSkillName(rawName);
  if (!name) {
    outputError(ctx, "invalid_skill_name", `'${sanitize(rawName)}' is not a valid skill name.`, ExitCodes.USAGE, "Pass a skill name like '10x-plan'.");
  }
  const lang = resolveLanguage(ctx, options.lang);
  const scope = resolveCourseScope(ctx, options.course, process.cwd());

  const auth = await requireAuth(ctx);

  verbose(ctx, `fetching skill overviews ${JSON.stringify({ course: scope.course, lang })}`);
  const result = await fetchSkillOverviews(auth.access_token, { ...(scope.course !== undefined ? { course: scope.course } : {}), lang });
  if (!result.ok) handleError(ctx, result.status, result.code, result.error, scope);

  const overviews = result.data.overviews;
  const overview = overviews.find((item) => item.name === name) ?? overviews.find((item) => item.name === `10x-${name}`);
  if (!overview) notFound(ctx, name, overviews, scope);

  if (ctx.json) {
    output(ctx, "", { course: scope.course ?? null, overview });
    return;
  }
  const width = Math.min(process.stderr.columns || 80, MAX_WIDTH);
  output(ctx, renderOverview(overview, width).join("\n"), undefined);
}

function resolveLanguage(ctx: OutputContext, raw: unknown): SkillOverviewLanguage {
  const fromFlag = raw !== undefined;
  const value = fromFlag ? raw : readToolConfig()?.lang;
  const known = LANGUAGES.find((lang) => lang === value);
  if (known) return known;
  // A stale configured value is not this invocation's mistake.
  if (!fromFlag) return "en";
  outputError(ctx, "invalid_lang", `Unknown language '${sanitize(String(raw))}'.`, ExitCodes.USAGE, `Supported languages: ${LANGUAGES.join(", ")}`);
}

function notFound(ctx: OutputContext, name: string, overviews: SkillOverview[], scope: CourseScope): never {
  const where = scope.course ? ` in ${sanitize(scope.course)}` : "";
  if (overviews.length === 0) {
    outputError(ctx, "skill_overview_not_found", `No skill overviews are published${where} yet.`, ExitCodes.NOT_FOUND, "Try again later; '10x get' and '10x sync' still deliver the skills themselves.");
  }
  const suggestions = suggestSkills(name, overviews.map((item) => item.name)).map(sanitize);
  const hint = suggestions.length > 0
    ? `Did you mean: ${suggestions.join(", ")}?`
    : scope.course ? "Skills are listed per course; try '--course <course>' for another one." : "Check the name in your '.claude/skills' folder or the 10xDevs lesson.";
  outputError(ctx, "skill_overview_not_found", `No overview for skill '${sanitize(name)}'${where}.`, ExitCodes.NOT_FOUND, hint);
}

function handleError(ctx: OutputContext, status: number, code: string, error: string, scope: CourseScope): never {
  if (code === "skill_overviews_unsupported") {
    outputError(ctx, code, "The 10x-toolkit API does not serve skill overviews yet.", ExitCodes.ERROR, "Try again later; '10x get' and '10x sync' still work.");
  }
  if (status === 403) {
    outputError(
      ctx,
      "course_access_denied",
      scope.course ? `Your account does not have access to ${scope.course}.` : "Your account has no active course access.",
      ExitCodes.FORBIDDEN,
      scope.source === "project" ? `This project uses ${scope.course}.` : undefined,
    );
  }
  if (status === 404 && code === "course_not_found") {
    outputError(ctx, "course_not_found", `Unknown course: ${scope.course}.`, ExitCodes.USAGE, "Use a course id such as '10xdevs4'.");
  }
  if (status === 401) {
    outputError(ctx, "auth_required", "Your session is no longer valid.", ExitCodes.AUTH_REQUIRED, "Run '10x auth' to log in again.");
  }
  if (status === 0 && code === "network_error") {
    outputError(ctx, "network_error", "Could not reach the 10x-toolkit API.", ExitCodes.ERROR, "Check your internet connection and try again.");
  }
  outputError(ctx, code || "skill_overviews_failed", error || "Failed to load the skill overview.", ExitCodes.ERROR);
}

const LABELS: Record<SkillOverviewLanguage, { problem: string; solution: string; whenToUse: string; artifacts: string; noArtifacts: string; related: string }> = {
  en: { problem: "Problem", solution: "Solution", whenToUse: "Use when", artifacts: "Produces", noArtifacts: "No files.", related: "Related" },
  pl: { problem: "Problem", solution: "Rozwiązanie", whenToUse: "Kiedy", artifacts: "Tworzy", noArtifacts: "Bez plików.", related: "Powiązane" },
};

/**
 * Glossary layout: a heading, then one aligned label per section. Every string
 * is remote-controlled, so it is sanitized before it reaches the terminal;
 * wrapping happens before styling so ANSI codes never count toward the width.
 */
export function renderOverview(overview: SkillOverview, width: number): string[] {
  const labels = LABELS[overview.language] ?? LABELS.en;
  const column = Math.max(labels.problem.length, labels.solution.length, labels.whenToUse.length, labels.artifacts.length, labels.related.length) + 2;
  const indent = " ".repeat(column);
  const label = (text: string) => paint(STYLE.bold, text.padEnd(column));
  /** `wrapped` starts with `indent`; swap it for the section label. */
  const withLabel = (text: string, wrapped: string[]) => wrapped.map((line, i) => (i === 0 ? label(text) + line.slice(column) : line));

  const lines = [
    paint(STYLE.bold, paint(STYLE.cyan, `/${sanitize(overview.name)}`)),
    ...wrapText(sanitize(overview.stage), width, "").map((line) => paint(STYLE.dim, line)),
    "",
  ];
  for (const [title, text] of [
    [labels.problem, overview.problem],
    [labels.solution, overview.solution],
    [labels.whenToUse, overview.whenToUse],
  ] as const) {
    lines.push(...withLabel(title, wrapText(sanitize(text), width, indent)));
  }

  lines.push("");
  if (overview.artifacts.length === 0) {
    lines.push(label(labels.artifacts) + labels.noArtifacts);
  }
  overview.artifacts.forEach((artifact, i) => {
    const first = i === 0 ? label(labels.artifacts) : indent;
    lines.push(first + paint(STYLE.green, sanitize(artifact.path)));
    lines.push(...wrapText(sanitize(artifact.purpose), width, `${indent}  `).map((line) => paint(STYLE.dim, line)));
  });

  if (overview.related.length > 0) {
    lines.push("");
    const nameWidth = Math.max(...overview.related.map((item) => sanitize(item.name).length)) + 3;
    overview.related.forEach((item, i) => {
      const name = `/${sanitize(item.name)}`;
      const prefix = " ".repeat(column + nameWidth);
      const wrapped = wrapText(sanitize(item.why), width, prefix);
      wrapped.forEach((line, j) => {
        if (j > 0) lines.push(line);
        else lines.push((i === 0 ? label(labels.related) : indent) + paint(STYLE.cyan, name) + " ".repeat(nameWidth - name.length) + line.slice(prefix.length));
      });
    });
  }
  return lines;
}
